executeFunc(function authYandex(){const authLink=document.getElementById("yandex-auth-link");if(typeof authLink==="undefined"||authLink===null){return false}authLink.addEventListener("click",function(event){const modal=document.getElementById("modal");if(modal){let currentmodal=bootstrap.Modal.getOrCreateInstance(modal);currentmodal.hide()}event.preventDefault();const authUrl=this.href;const width=600;const height=700;const left=(screen.width-width)/2;const top=(screen.height-height)/2;const features=`width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`;const authWindow=window.open(authUrl,"yandexAuth",features);if(authWindow){authWindow.focus()}else{alert("Не удалось открыть окно авторизации. Разрешите всплывающие окна.")}});window.addEventListener("message",function(event){if(event.data.type==="YANDEX_AUTH_SUCCESS"){window.location.replace(window.location.origin)}if(event.data.type==="YANDEX_AUTH_FALIED"){let $successSupplyToast='{ "type":"danger" , '+'"header":"Авторизация Яндекс"  , '+'"message" : "Ошибка аутентификации" }';createToast(JSON.parse($successSupplyToast))}});return true});